function parseThresholdArg(raw: string): { metric: string; min: number } {
  const eqIndex = raw.indexOf('=');
  const metric = eqIndex >= 0 ? raw.slice(0, eqIndex).trim() : '';
  const minRaw = eqIndex >= 0 ? raw.slice(eqIndex + 1).trim() : '';

  if (!metric || !minRaw || Number.isNaN(Number(minRaw))) {
    throw new Eval.ThresholdValidationError(
      `Invalid --threshold value "${raw}". Expected format <metric>=<min>, e.g. exact_match=0.9.`
    );
  }

  return { metric, min: Number(minRaw) };
}

function runEvalCommand(options: EvalOptions) {
  try {
    assertFileExists(options.outputs);
    const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
