        generateReport({
          evaluations,
          outputsPath: '/tmp/outputs.json',
          thresholds: { exact_match: 1.5 }
        })
      ).toThrow(ThresholdValidationError);
    });

    it('leaves the report unchanged when no thresholds are supplied', () => {
      const evaluations = runEvaluations({ outputs: ['hello'], references: ['hello'] });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json'
      });

